package com.shopsphere;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.UUID;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/cart") @org.springframework.security.access.prepost.PreAuthorize("#userId.toString() == authentication.name")public class CartController{private final CartService service;CartController(CartService s){service=s;}record Add(@NotNull UUID productId,@Positive int quantity){}record Quantity(@Positive int quantity){}@GetMapping("/{userId}")Cart get(@PathVariable UUID userId){return service.get(userId);}@PostMapping("/{userId}/items")@ResponseStatus(HttpStatus.CREATED)Cart add(@PathVariable UUID userId,@Valid@RequestBody Add r){return service.add(userId,r.productId(),r.quantity());}@PutMapping("/{userId}/items/{productId}")Cart update(@PathVariable UUID userId,@PathVariable UUID productId,@Valid@RequestBody Quantity r){return service.update(userId,productId,r.quantity());}@DeleteMapping("/{userId}/items/{productId}")Cart remove(@PathVariable UUID userId,@PathVariable UUID productId){return service.remove(userId,productId);}@DeleteMapping("/{userId}")@ResponseStatus(HttpStatus.NO_CONTENT)void clear(@PathVariable UUID userId){service.clear(userId);}}
